CREATE TABLE "cities" (
  "id" int PRIMARY KEY,
  "name" text UNIQUE NOT NULL
);

CREATE TABLE "sport" (
  "id" int PRIMARY KEY NOT NULL,
  "name" varchar(31) NOT NULL,
  "sport_category" varchar(15) NOT NULL,
  "min_players_per_team" int NOT NULL,
  "max_players_per_team" int NOT NULL,
  "minutes_per_round" int NOT NULL,
  "minutes_per_pause" int NOT NULL,
  "min_referee" int NOT NULL
);

CREATE TABLE "account" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "firebase_uid" varchar(255) UNIQUE,
  "stripe_id" varchar(255) UNIQUE,
  "username" varchar(15) UNIQUE NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "phone" varchar(15) UNIQUE NOT NULL,
  "name" varchar(31) NOT NULL,
  "surname" varchar(31) NOT NULL,
  "vip" bool DEFAULT false NOT NULL,
  "vip_type" varchar(15) DEFAULT 'NONE',
  "vip_start" date,
  "vip_end" date,
  "role" varchar(15) NOT NULL,
  "status" varchar(15) DEFAULT 'ACTIVE',
  "preferred_city_id" int,
  "favorite_sport_category" varchar(15) NOT NULL DEFAULT 'FOOTBALL',
  "created_at" timestamp DEFAULT now(),
  "last_login" timestamp DEFAULT now()
);

CREATE TABLE "player" (
  "player_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int UNIQUE NOT NULL,
  "points" int NOT NULL DEFAULT '0'
);

CREATE TABLE "coordinator" (
  "coordinator_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int UNIQUE NOT NULL,
  "level" smallint NOT NULL DEFAULT 1
);

CREATE TABLE "referee" (
  "referee_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int UNIQUE NOT NULL,
  "level" smallint NOT NULL DEFAULT 1
);

CREATE TABLE "organization" (
  "organization_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int UNIQUE NOT NULL,
  "org_name" varchar(255) NOT NULL
);

CREATE TABLE "account_restriction" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int NOT NULL,
  "type" varchar(31) NOT NULL,
  "valid_from" date NOT NULL,
  "valid_to" date,
  "created_at" timestamp NOT NULL DEFAULT NOW()
);

CREATE TABLE "friend_invite" (
  "invited_account_id" int PRIMARY KEY,
  "inviter_account_id" int NOT NULL,
  "redeemed" bool NOT NULL DEFAULT false
);

CREATE TABLE "growth_step" (
  "type" varchar(15) NOT NULL,
  "title" varchar(31) NOT NULL,
  "level" smallint NOT NULL,
  "x" int NOT NULL,
  "min_rating_over_last_x_games" numeric(3,2),
  "min_refereed_games" smallint,
  "min_rating_over_last_x_tournaments" numeric(3,2),
  "min_coordinated_tournaments" smallint,
  "coordinator_pay_per_game" numeric(10,2)
  primary key ("type", "level")
);

CREATE TABLE "field" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" int NOT NULL,
  "city_id" int NOT NULL,
  "name" varchar(31),
  "location_lat" double precision NOT NULL,
  "location_lng" double precision NOT NULL,
  "address" varchar(63) NOT NULL,
  "hour_cost_tournament" numeric(10,2) NOT NULL,
  "hour_cost_private" numeric(10,2) NOT NULL,
  "opening_time" time NOT NULL,
  "closing_time" time NOT NULL,
  "closed_days" char(7) NOT NULL DEFAULT '0000001'
);

CREATE TABLE "field_category" (
  "field_id" int NOT NULL,
  "sport_category" varchar(15) NOT NULL,
  "max_players" smallint NOT NULL
);

CREATE TABLE "referee_role" (
  "sport_id" int,
  "name" varchar(15) NOT NULL,
  "level" smallint NOT NULL,
  "pay_per_match" numeric(10,2) NOT NULL,
  PRIMARY KEY ("sport_id", "name", "level")
);

CREATE TABLE "referee_license" (
  "referee_id" int,
  "sport_id" int,
  "photo_url" varchar(255),
  "status" varchar(31) DEFAULT 'NOT_VERIFIED',
  "issued_at" date NOT NULL,
  "verified_at" timestamp,
  "expires_at" date,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("sport_id", "referee_id")
);

CREATE TABLE "team" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "city_id" int,
  "captain_player_id" int NOT NULL,
  "vice1_player_id" int,
  "vice2_player_id" int,
  "logo_url" varchar(255),
  "name" varchar(31) NOT NULL,
  "alias" char(3) NOT NULL,
  "description" varchar(511),
  "players" int NOT NULL DEFAULT 1,
  "max_players" int NOT NULL DEFAULT 24,
  "rank_pts" int NOT NULL DEFAULT 0,
  "sport_category" varchar(15) NOT NULL,
  "vip" bool NOT NULL DEFAULT false
);

CREATE TABLE "plays_at" (
  "team_id" int NOT NULL,
  "player_id" int NOT NULL,
  "sport_category" varchar(15) NOT NULL,
  PRIMARY KEY ("team_id", "player_id")
);

CREATE TABLE "team_request" (
  "team_id" int NOT NULL,
  "player_id" int NOT NULL,
  PRIMARY KEY ("team_id", "player_id")
);

CREATE TABLE "football_team_stat" (
  "player_id" int NOT NULL,
  "team_id" int NOT NULL,
  "goals" int NOT NULL DEFAULT 0,
  "motm" int NOT NULL DEFAULT 0,
  "red_cards" int NOT NULL DEFAULT 0,
  "yellow_cards" int NOT NULL DEFAULT 0
);

CREATE TABLE "booking" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "field_id" int NOT NULL,
  "cancel_description" varchar(255),
  "status" varchar(15) NOT NULL DEFAULT 'BOOKED',
  "sport_category" varchar(15) NOT NULL,
  "start_time" timestamp NOT NULL,
  "finish_time" timestamp NOT NULL,
  "booking_type" varchar(15) NOT NULL
);

CREATE TABLE "private_booking" (
  "id" int PRIMARY KEY,
  "player_id" int NOT NULL,
  "cost" numeric(10,2) NOT NULL
);

CREATE TABLE "lobby_booking" (
  "id" int PRIMARY KEY,
  "owner_player_id" int NOT NULL,
  "players_to_find" smallint NOT NULL,
  "total_players" smallint NOT NULL,
  "fee_per_player" numeric(10,2) NOT NULL
);

CREATE TABLE "lobby_booking_participate" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" int NOT NULL,
  "lobby_booking_id" int NOT NULL,
  "players_paid" smallint NOT NULL DEFAULT 1,
  "cost" numeric(10,2) NOT NULL,
  "transaction_group_id" int NOT NULL,
  "joined_at" timestamp NOT NULL DEFAULT NOW()
);

CREATE TABLE "match_booking" (
  "id" int PRIMARY KEY,
  "coordinator_id" int NOT NULL,
  "match_id" int NOT NULL
);

CREATE TABLE "tournament" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "coordinator_id" int NOT NULL,
  "field_id" int NOT NULL,
  "city_id" int NOT NULL,
  "sport_id" int NOT NULL,
  "public" bool NOT NULL DEFAULT true,
  "profit" bool NOT NULL DEFAULT true,
  "pay_coordinator" numeric(10,2) NOT NULL,
  "fee" numeric(10,2) NOT NULL,
  "prize1" numeric(10,2) NOT NULL,
  "prize2" numeric(10,2) NOT NULL DEFAULT 0,
  "num_teams" smallint NOT NULL DEFAULT 8,
  "num_groups" smallint NOT NULL DEFAULT 2,
  "round2_group_stage" bool NOT NULL DEFAULT false,
  "round2_final_stage" bool NOT NULL DEFAULT false,
  "num_teams_qualified" smallint NOT NULL DEFAULT 4,
  "name" varchar(31),
  "description" varchar(511) NOT NULL,
  "status" varchar(31) NOT NULL DEFAULT 'CREATED',
  "phase" varchar(31) NOT NULL DEFAULT 'GROUP_STAGE',
  "paid_teams" smallint NOT NULL DEFAULT '0',
  "atl_event" bool NOT NULL DEFAULT false,
  "photo_url" varchar(255),
  "start_date" date
);

CREATE TABLE "favorite_tournament" (
  "account_id" int NOT NULL,
  "tournament_id" int NOT NULL,
  PRIMARY KEY ("account_id", "tournament_id")
);

CREATE TABLE "tournament_participation" (
  "tournament_id" int,
  "team_id" int,
  "to_pay" numeric(10,2) NOT NULL,
  PRIMARY KEY ("tournament_id", "team_id")
);

CREATE TABLE "failed_tournament_participation" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" int,
  "team_id" int
);

CREATE TABLE "callup" (
  "tournament_id" int NOT NULL,
  "team_id" int NOT NULL,
  "player_id" int NOT NULL,
  "prize_to_redeem" numeric(10,2)
);

CREATE TABLE "palmares" (
  "tournament_id" int NOT NULL,
  "team_id" int NOT NULL,
  "position" varchar(31) NOT NULL DEFAULT 'GROUP_STAGE'
);

CREATE TABLE "football_tournament_stats" (
  "player_id" int NOT NULL,
  "tournament_id" int NOT NULL,
  "team_id" int NOT NULL,
  "goals" int NOT NULL DEFAULT 0,
  "motm" int NOT NULL DEFAULT 0,
  "yellow_cards" int NOT NULL DEFAULT 0,
  "red_cards" int NOT NULL DEFAULT 0,
  PRIMARY KEY ("player_id", "tournament_id")
);

CREATE TABLE "football_standing" (
  "tournament_id" int NOT NULL,
  "team_id" int NOT NULL,
  "group_name" varchar(3),
  "won" smallint NOT NULL DEFAULT 0,
  "pts" smallint NOT NULL DEFAULT 0,
  "drawn" smallint NOT NULL DEFAULT 0,
  "lost" smallint NOT NULL DEFAULT 0,
  "goals_scored" smallint NOT NULL DEFAULT 0,
  "goals_conceded" smallint NOT NULL DEFAULT 0,
  "rank_pos" smallint NOT NULL DEFAULT 1,
  "qualified" bool NOT NULL DEFAULT false,
  PRIMARY KEY ("tournament_id", "team_id")
);

CREATE TABLE "match" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" int NOT NULL,
  "motm" int,
  "group_name" varchar(3),
  "scheduled_start" timestamp,
  "start_match" timestamp,
  "finish_match" timestamp,
  "coordinator_status" text NOT NULL DEFAULT 'ASSIGNED',
  "sport_category" varchar(15) NOT NULL,
  "final_stage_bracket_id" int,
  "leg_order" varchar(15) DEFAULT 'FIRST_LEG'
);

CREATE TABLE "final_stage_bracket"(
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" int NOT NULL,
  "group_name" varchar(3) NOT NULL,
  "aggregate_score_home" smallint NOT NULL DEFAULT 0,
  "aggregate_score_away" smallint NOT NULL DEFAULT 0,
  "next_final_stage_bracket_id" int,
  "next_final_stage_bracket_slot" varchar(15) DEFAULT 'HOME'
);

CREATE TABLE "referee_assignment" (
  "match_id" int NOT NULL,
  "referee_id" int NOT NULL,
  "role" varchar(15) NOT NULL,
  "pay" numeric(10,2) NOT NULL,
  "status" varchar(15) NOT NULL DEFAULT 'ASSIGNED'
);

CREATE TABLE "football_match" (
  "id" int PRIMARY KEY,
  "home_team_id" int,
  "away_team_id" int,
  "score_home" smallint,
  "penalty_score_home" smallint,
  "missed_penalty_home" smallint,
  "score_away" smallint,
  "penalty_score_away" smallint,
  "missed_penalty_away" smallint,
  "halftime" timestamp,
  "start_half" timestamp,
  "status" varchar(31) NOT NULL DEFAULT 'NOT_SCHEDULED'
);

CREATE TABLE "football_match_event" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" int NOT NULL,
  "team_id" int,
  "player_id" int,
  "type" varchar(31) NOT NULL,
  "minute" smallint NOT NULL,
  "additional_minute" smallint NOT NULL,
  "modified_table" JSONB
);

CREATE TABLE "review" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" int NOT NULL,
  "reviewer_account_id" int NOT NULL,
  "reviewed_account_id" int NOT NULL,
  "comment" varchar(255),
  "rating" numeric(3,2) NOT NULL,
  "weight" numeric(3,2) NOT NULL DEFAULT 0.5,
  "review_type" varchar(31) NOT NULL,
  "status" varchar(15) NOT NULL DEFAULT 'WAITING',
  "sport_category" varchar(15) NOT NULL,
  "linked_transaction_id" int,
  "created_at" timestamp NOT NULL DEFAULT NOW(),
  "committed_at" timestamp
);

CREATE TABLE "wallet" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int UNIQUE NOT NULL,
  "prize_balance" numeric(10,2) NOT NULL DEFAULT 0,
  "personal_balance" numeric(10,2) NOT NULL DEFAULT 0,
  "invite_balance" numeric(10,2) NOT NULL DEFAULT 0,
  "prize_last_withdraw" timestamp,
  "personal_last_withdraw" timestamp
);

CREATE TABLE "checkout_session" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int,
  "type" varchar(31) NOT NULL,
  "status" varchar(15) NOT NULL,
  "payload" JSONB NOT NULL,
  "amount" numeric(10,2) NOT NULL,
  "created_at" timestamp NOT NULL,
  "expires_at" timestamp NOT NULL
);

CREATE TABLE "purchase" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int,
  "object_id" int NOT NULL,
  "type" varchar(31) NOT NULL,
  "detail" JSONB NOT NULL,
  "status" varchar(15) NOT NULL DEFAULT 'CONFIRMED',
  "transaction_group_id" int NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT NOW()
);

CREATE TABLE "transaction" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" int NOT NULL,
  "source" varchar(31) NOT NULL,
  "status" varchar(15) NOT NULL DEFAULT 'PENDING',
  "type" varchar(15) NOT NULL,
  "amount" numeric(10,2) NOT NULL,
  "net_amount" numeric(10,2) NOT NULL,
  "fee" numeric(10,2),
  "tax" numeric(10,2),
  "currency" char(3) NOT NULL DEFAULT 'EUR',
  "stripe_payment_intent_id" varchar(255),
  "idempotency_key" varchar(255),
  "pending_reason" varchar(31),
  "transaction_group_id" int NOT NULL,
  "related_transaction_id" int,
  "refundable" bool NOT NULL DEFAULT true,
  "visible" bool NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT NOW(),
  "processed_at" timestamp
);

CREATE TABLE "transaction_group" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "status" varchar(15) NOT NULL DEFAULT 'PENDING',
  "created_at" timestamp NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX ON "plays_at" ("player_id", "sport_category");

CREATE UNIQUE INDEX ON "final_stage_bracket" ("tournament_id", "group_name");

CREATE UNIQUE INDEX ON "team" ("vice1_player_id", "sport_category") WHERE "vice1_player_id" IS NOT NULL;

CREATE UNIQUE INDEX ON "team" ("vice2_player_id", "sport_category") WHERE "vice2_player_id" IS NOT NULL;

CREATE UNIQUE INDEX ON "team" ("captain_player_id", "sport_category");

CREATE UNIQUE INDEX ON "team" ("name", "sport_category");

COMMENT ON TABLE "cities" IS 'Utile per avere le città di ATL';

COMMENT ON TABLE "sport" IS 'Ha gli sport in modo ordinato';

COMMENT ON TABLE "account" IS 'Entità generale User. Ogni utente può avere un solo ruolo (Player, Coordinator, Referee, Organization).';

COMMENT ON TABLE "field" IS 'Campo sportivo gestito da un’organizzazione.';

COMMENT ON TABLE "field_category" IS 'A quanto pare un campo può essere usato da più sport';

COMMENT ON TABLE "referee_role" IS 'Ogni sport ha i suoi arbitri. A seconda del livello, c è un pagamento';

COMMENT ON TABLE "team" IS 'Ci sono i teams e le informazioni. Ricorda di gestire che il nome è univoco solo se Ogni squadra ha 24 partecipanti massimo, indipendentemente dallo sport.';

COMMENT ON TABLE "tournament" IS 'Campi del torneo';

COMMENT ON TABLE "football_tournament_stats" IS 'Ogni torneo ha le sue statistiche';

